"""Exact pH of polyprotic acids by solving the full charge balance with bisection."""

import math

Kw = 1e-14


def deprotonation_charge(h, kas):
    """Average number of released protons per acid molecule, sum(i * alpha_i).

    Species distribution for H_nA with stepwise constants kas = [Ka1..Kan]:
      denominator D = h^n + Ka1*h^(n-1) + Ka1*Ka2*h^(n-2) + ...
      alpha_i (i deprotonations) = (Ka1*...*Kai) * h^(n-i) / D
    """
    n = len(kas)
    # terms[i] = product of first i Kas times h^(n-i)
    terms = []
    prod = 1.0
    for i in range(n + 1):
        terms.append(prod * h ** (n - i))
        if i < n:
            prod *= kas[i]
    d = sum(terms)
    return sum(i * terms[i] for i in range(n + 1)) / d


def solve_ph(conc, kas, ph_lo=0.0, ph_hi=14.0, tol=1e-12, max_iter=200):
    """pH of a diprotic/triprotic/etc. acid of formal concentration `conc`.

    Charge balance:  [H+] = [OH-] + conc * sum(i * alpha_i)
    Solved by bisection on pH in [ph_lo, ph_hi]; f(pH) increases with [H+].
    """
    def imbalance(ph):
        h = 10.0 ** (-ph)
        return h - Kw / h - conc * deprotonation_charge(h, kas)

    f_lo, f_hi = imbalance(ph_lo), imbalance(ph_hi)
    if f_lo == 0.0:
        return ph_lo
    if f_hi == 0.0:
        return ph_hi
    if f_lo * f_hi > 0:
        raise ValueError("charge balance not bracketed on [%g, %g]" % (ph_lo, ph_hi))
    for _ in range(max_iter):
        mid = 0.5 * (ph_lo + ph_hi)
        if (ph_hi - ph_lo) < tol:
            break
        f_mid = imbalance(mid)
        if f_mid == 0.0:
            return mid
        if f_lo * f_mid < 0:
            ph_hi, f_hi = mid, f_mid
        else:
            ph_lo, f_lo = mid, f_mid
    return 0.5 * (ph_lo + ph_hi)


def quad_approx_ph(conc, ka1):
    """First-dissociation quadratic approximation: x^2/(C - x) = Ka."""
    x = (-ka1 + math.sqrt(ka1 * ka1 + 4.0 * ka1 * conc)) / 2.0
    return -math.log10(x)

